const SIGIL_ASTROLABE = (() => {
  const quads: readonly [number, number][] = [
    [-162, -105],
    [-75, -18],
    [18, 75],
    [105, 162],
  ];
  const arcs: { d: string; tier: 1 | 2 | 3 }[] = [];
  const hooks: { cx: number; cy: number }[] = [];
  const cx = 340;
  const cy = 340;

  const makeArc = (r: number, a0: number, a1: number) => {
    const s = (a0 * Math.PI) / 180;
    const e = (a1 * Math.PI) / 180;
    const x1 = cx + Math.cos(s) * r;
    const y1 = cy + Math.sin(s) * r;
    const x2 = cx + Math.cos(e) * r;
    const y2 = cy + Math.sin(e) * r;
    return `M ${x1.toFixed(1)} ${y1.toFixed(1)} A ${r} ${r} 0 0 1 ${x2.toFixed(1)} ${y2.toFixed(1)}`;
  };

  for (const [a0, a1] of quads) {
    arcs.push({ d: makeArc(287, a0, a1), tier: 1 });
    arcs.push({ d: makeArc(271.5, a0 + 3, a1 - 3), tier: 2 });
    arcs.push({ d: makeArc(263, a0 + 7, a1 - 7), tier: 3 });

    const s = ((a0 + 3) * Math.PI) / 180;
    const e = ((a1 - 3) * Math.PI) / 180;
    hooks.push({
      cx: Number((cx + Math.cos(s) * 262.5 - Math.sin(s) * 6).toFixed(1)),
      cy: Number((cy + Math.sin(s) * 262.5 + Math.cos(s) * 6).toFixed(1)),
    });
    hooks.push({
      cx: Number((cx + Math.cos(e) * 262.5 + Math.sin(e) * 6).toFixed(1)),
      cy: Number((cy + Math.sin(e) * 262.5 - Math.cos(e) * 6).toFixed(1)),
    });
  }

  return { arcs, hooks };
})();

/**
 * Bespoke B-04 Sibling Case-Folio Seals (I. Still Life through V. Sacred Forest).
 * Unifies all 5 project sigils with the core brand grammar: flat silver-ivory stencil-cut
 * silhouettes, 45-degree negative-space cuts, Victorian volutes, crimson-garnet core inlays,
 * and counter-rotating broken double-astrolabe & 45-degree diamond gimbals on hover.
 */
export function ProjectSigil({
  slug,
  variant = "gilt",
  className = "h-24 w-24",
}: ProjectSigilProps) {
  const isGilt = variant === "gilt";
  const spec = SIGIL_VECTORS[slug] ?? SIGIL_VECTORS["sacred-forest"];

  const fg = isGilt ? "#f5ebd6" : "#1a1310";
  const muted = isGilt ? "#d4b888" : "#6e5438";
  const crimson = isGilt ? "#be2024" : "#8a181a";
  const crimsonRim = isGilt ? "rgba(245, 235, 214, 0.36)" : "none";

  return (
    <svg
      viewBox="16 16 648 648"
      fill="none"
      aria-hidden="true"
      className={`select-none overflow-visible ${
        isGilt
          ? "[filter:drop-shadow(0_4px_10px_rgba(0,0,0,0.92))_drop-shadow(0_0.5px_0_rgba(255,244,214,0.28))]"
          : "[filter:drop-shadow(0_1px_0_rgba(255,252,242,0.85))]"
      } ${className}`}
    >
      {/* 1. Outer Broken Double-Astrolabe Gimbal (counter-rotates on parent folder/card group-hover) */}
      <g
        style={{ transformBox: "view-box", transformOrigin: "340px 340px" }}
        className="transition-transform duration-700 ease-[cubic-bezier(0.16,1,0.3,1)] group-hover:-rotate-[22deg]"
      >
        {SIGIL_ASTROLABE.arcs.map((arc, idx) => (
          <path
            key={idx}
            d={arc.d}
            fill="none"
            stroke={muted}
            strokeWidth={arc.tier === 1 ? 2.4 : arc.tier === 2 ? 1.7 : 1.25}
            opacity={arc.tier === 3 ? 0.78 : 0.94}
          />
        ))}
        {SIGIL_ASTROLABE.hooks.map((h, idx) => (
          <circle
            key={idx}
            cx={h.cx}
            cy={h.cy}
            r="4.5"
            fill="none"
            stroke={muted}
            strokeWidth="1.45"
            opacity="0.86"
          />
        ))}
        <line x1="340" y1="20" x2="340" y2="50" stroke={muted} strokeWidth="2.0" />
        <line x1="340" y1="630" x2="340" y2="660" stroke={muted} strokeWidth="2.0" />
        <line x1="20" y1="340" x2="50" y2="340" stroke={muted} strokeWidth="2.0" />
        <line x1="630" y1="340" x2="660" y2="340" stroke={muted} strokeWidth="2.0" />
      </g>

      {/* 2. Rotated 45-Degree Double-Diamond & Side Crescent Brackets */}
      <g
        style={{ transformBox: "view-box", transformOrigin: "340px 340px" }}
        className="transition-transform duration-600 ease-[cubic-bezier(0.16,1,0.3,1)] group-hover:rotate-[45deg]"
      >
        <polygon points="340,60 620,340 340,620 60,340" fill="none" stroke={muted} strokeWidth="2.25" />
        <polygon
          points="340,73 607,340 340,607 73,340"
          fill="none"
          stroke={muted}
          strokeWidth="1.45"
          opacity="0.82"
        />
        <path d="M 122 292 A 223 223 0 0 0 122 388 A 232 232 0 0 1 122 292 Z" fill={muted} opacity="0.8" />
        <path d="M 558 292 A 223 223 0 0 1 558 388 A 232 232 0 0 0 558 292 Z" fill={muted} opacity="0.8" />
      </g>

      {/* 3. Bespoke Stencil-Cut Folio Silhouette & Crimson-Garnet Core */}
      <path d={spec.fg} fill={fg} fillRule="evenodd" />
      <path
        d={spec.crimson}
        fill={crimson}
        stroke={crimsonRim}
        strokeWidth={isGilt ? "1.6" : "0"}
        fillRule="evenodd"
      />
    </svg>
  );
}
